document.querySelector("#batch38 .grid").insertAdjacentHTML("beforeend","<a class=\"card\" href=\"summaries/sallabi-54.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف المغول التتار بين الانتشار والانكسار\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">تاريخ · مجاني رسمي</span><h3>المغول التتار بين الانتشار والانكسار</h3><p>تبدأ خطة المقدمة بالمجتمع المغولي وتوحيد القبائل وبناء الإمبراطورية، ثم تتجه إلى الصدام مع القوى الإسلامية. وتعطي التنظيم العسكري والاتصال والقيا…</p><small>علي محمد محمد الصلابي</small></a><a class=\"card\" href=\"summaries/sallabi-37.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف الدولة الأموية: عوامل الازدهار وتداعيات الانهيار\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">تاريخ · مجاني رسمي</span><h3>الدولة الأموية: عوامل الازدهار وتداعيات الانهيار</h3><p>تثبت صفحتا العنوان أن الملفين جزآن من العمل نفسه. تبدأ مقدمة الجزء الأول بالجذور الأموية وبسيرة معاوية وصلاته بالعهدين النبوي والراشدي، وتعلن خطة…</p><small>علي محمد محمد الصلابي</small></a><a class=\"card\" href=\"summaries/sallabi-21.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف كفاح الشعب الجزائري ضد الاحتلال الفرنسي\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">تاريخ · مجاني رسمي</span><h3>كفاح الشعب الجزائري ضد الاحتلال الفرنسي</h3><p>تعرف مقدمة الجزء الأول المشروع باعتباره بداية موسوعة كفاح الشعوب، وتعود إلى سياقات الأندلس والشمال الإفريقي والوجود العثماني قبل الاحتلال الفرنسي…</p><small>علي محمد محمد الصلابي</small></a>");
